#include <stdio.h>

#define MAXN 100000

long long h[MAXN];
long long leftMax[MAXN];
long long rightMax[MAXN];

int main(void) {
    int n;
    scanf("%d", &n);

    for (int i = 0; i < n; i++) {
        scanf("%lld", &h[i]);
    }

    long long mx = 0;
    for (int i = 0; i < n; i++) {
        if (h[i] > mx) mx = h[i];
        leftMax[i] = mx;
    }

    mx = 0;
    for (int i = n - 1; i >= 0; i--) {
        if (h[i] > mx) mx = h[i];
        rightMax[i] = mx;
    }

    int answer = 0;
    for (int i = 0; i < n; i++) {
        long long waterLevel = leftMax[i] < rightMax[i] ? leftMax[i] : rightMax[i];
        if (waterLevel - h[i] >= 1) {
            answer++;
        }
    }

    printf("%d\n", answer);
    return 0;
}
